head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vBzProcsNo = "";
scwin.MSG_TR_DOME = "작업이 정상적으로 처리되었습니다.";
scwin.MSG_TR_FAIL = "처리 중 오류가 발생하였습니다.";
scwin.fn_GetPar, scwin.fn_SetPar, scwin.strKeyLstBzProcsNo = "", scwin.strKeyIsurCd = "";
scwin.contnId;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const arr = new Array();
        const parentWin = $c.frame.path("../");
        scwin.fn_GetPar = parentWin.scwin.fn_GetPar;
        scwin.fn_SetPar = parentWin.scwin.fn_SetPar;
        if (scwin.fn_GetPar !== undefined) {
            scwin.fn_GetPar(arr);
        }
        txb_IsurCd.setValue((arr.length >= 1 ? arr[0] : ""));
        txb_CoNm.setValue((arr.length >= 3 ? arr[2] : "")); // 발행기관명도 넘겨받아 컨트롤에 반영해야 한다.

        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        await scwin.searchWebRflct();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07302.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Cmt_OnLoadCompleted
 * @description dts_Cmt 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Cmt_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_Cmt.getRowCount() > 0) {
            fn_setKeyCtrOnUpd(); // 조회직후에는 수정상태
            fn_searchReqInf();
            // fn_fileSearch();
            fn_read();
        } else {
            if (confirm(MSG_NO_COMT)) {
                fn_addNewCmt();
            } else {
                await $c.win.closePopup(); // CloseFrame은 호출자가 있을경우 유효하다.

            }
        }
        /*
        fn_setPanReadOnlyOnLoad(dts_Cmt, pan_Cmt);
        med_ComiteDd.readOnly = true;
         */
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07302.dts_Cmt_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Cmt_OnRowPosChanged
 * @description Cmt On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_Cmt_OnRowPosChanged = function(row) {
    try {
        if (dts_Cmt.getRowCount() > 0) {
            if (dts_Cmt.getCellData(row, "BZ_PROCS_NO") !== "") {
                fn_searchReqInf();
            }

            // alert("fn_fileSearch");
            // fn_fileSearch();
            fn_read();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07302.dts_Cmt_OnRowPosChanged" });
    }
};

/**
 * @method
 * @name dts_ReqInf_OnLoadCompleted
 * @description dts_ReqInf 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ReqInf_OnLoadCompleted = function(rowcount) {
    try {
        med_LIST_DELIB_SCHDL_DD.PutSelClipText(0, 8, dts_ReqInf.getCellData(1, "LIST_DELIB_SCHDL_DD"));
        med_INVSTG_DTL_WEB_DP_DD.PutSelClipText(0, 8, dts_ReqInf.getCellData(1, "INVSTG_DTL_WEB_DP_DD"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07302.dts_ReqInf_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name tr_Save_OnFail
 * @description tr Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tr_Save_OnFail = async function() {
    try {
        await $c.win.alert(scwin.MSG_TR_FAIL);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07302.tr_Save_OnFail" });
    }
};

/**
 * @method
 * @name tr_Save_OnSuccess
 * @description tr Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tr_Save_OnSuccess = async function() {
    try {
        await $c.win.alert(scwin.MSG_TR_DOME);
        scwin.parentRefresh();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07302.tr_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07302.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Save_onclick = async function() {
    try {
        await scwin.save("I");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07302.img_Save_onclick" });
    }
};

/**
 * @method
 * @name img_SetInvstgDtlWebDpDd_onclick
 * @description img_SetInvstgDtlWebDpDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SetInvstgDtlWebDpDd_onclick = function() {
    try {
        scwin.showCalendar(med_INVSTG_DTL_WEB_DP_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07302.img_SetInvstgDtlWebDpDd_onclick" });
    }
};

/**
 * @method
 * @name img_SetListDelibSchdlDd_onclick
 * @description img_SetListDelibSchdlDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SetListDelibSchdlDd_onclick = function() {
    try {
        scwin.showCalendar(med_LIST_DELIB_SCHDL_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07302.img_SetListDelibSchdlDd_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchWebRflct
 * @description search function begin
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchWebRflct = async function() {
    uri += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_ReqInf",
        action : "/konex/PrelmInvstgKonex.do",
        ref : "",
        target : "dts_ReqInf=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name save
 * @description search function end
 * @param {*} jobType jobType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function(jobType) {
    if (rdo_InvstgDtlWebDpYn.getValue() === 'Y') {
        if (med_INVSTG_DTL_WEB_DP_DD.GetSelClipText(0, 8) === '') {
            await $c.win.alert("웹반영여부가 '예'로 체크되어 있으므로 웹반영일을 입력해 주십시오.");
            return;
        }
    }
    if (med_INVSTG_DTL_WEB_DP_DD.GetSelClipText(0, 8) !== '') {
        if (rdo_InvstgDtlWebDpYn.getValue() === 'N') {
            await $c.win.alert("웹반영일이 입력되어 있으므로 웹반영여부를 '예'로 체크해 주십시오.");
            return;
        }
    }
    const vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    tr_Save.KeyName = "toinb_dataid4";
    // [전환검토] tr_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : "U",
    //     BZ_PROCS_NO : scwin.vBzProcsNo,
    //     INVSTG_DTL_WEB_DP_YN : $c.stf.getObjectValue(rdo_InvstgDtlWebDpYn),
    //     INVSTG_DTL_WEB_DP_DD : med_INVSTG_DTL_WEB_DP_DD.GetSelClipText(0, 8),
    //     LIST_DELIB_SCHDL_DD : med_LIST_DELIB_SCHDL_DD.GetSelClipText(0, 8)
    // };
    const sbmOptions = {
        id : "sbm_tr_Save",
        action : "/konex/PrelmInvstgKonex.do",
        ref : "dts_ReqInf",
        target : "tr_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name showCalendar
 * @description show Calendar 처리
 * @param {*} o o
 * @returns {void}
 * @hidden N
 */
scwin.showCalendar = function(o) {
    if ((o !== undefined) && (!o.readOnly)) {
        popUpCalendar2(o);
    }
};

/**
 * @method
 * @name getUserId
 * @description get User Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.getUserId = function() {
    return js_emp_no;
};

/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    const fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
